verus! {
    /// Computes the greatest common divisor (GCD) of two positive integers.
    /// 
    /// # Parameters
    /// - `m`: A positive integer.
    /// - `n`: A positive integer.
    ///
    /// # Returns
    /// - The GCD of `m` and `n`.
    #[verifier::spec]
    fn gcd_i(m: int, n: int) -> (d: int)
        requires m > 0 && n > 0
        ensures d > 0
        ensures d == gcd(m, n) // where gcd is the mathematical GCD function
    {
        // Invariant: m > 0 && n > 0
        // Decreases: m + n
        let mut a = m;
        let mut b = n;

        while a != b {
            // Ensure that we are always working with positive integers
            assert(a > 0);
            assert(b > 0);

            if a > b {
                a = a - b; // Reduce a
            } else {
                b = b - a; // Reduce b
            }
        }

        // At this point, a == b, which is the GCD
        return a; // or b, since a == b
    }
}